using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using System.Threading;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class PrintExport {
  public static bool Candidate(CadPart p){return !p.Reference&&(p.Role=="housing"||p.Role=="gear"||p.Role=="fixed"||(p.Role=="shaft"&&p.Id.Contains("CARRIER")));}
  public static CadAssembly Select(CadAssembly source,IEnumerable<string> ids){if(source==null||!source.Valid)throw new Exception("Сначала постройте допустимую 3D-сборку.");var keys=ids==null?null:new HashSet<string>(ids);var result=new CadAssembly();result.Parts.AddRange(source.Parts.Where(p=>Candidate(p)&&(keys==null||keys.Contains(p.Id))));if(result.Parts.Count==0)throw new Exception("Выберите хотя бы одну деталь для печати.");result.Notes.Add("Только выбранные печатные заготовки; мотор, крепёж, подшипники, отдельные металлические валы/оси исключены. Прочность, материал и допуски нужно назначить.");return result;}
  public static SceneMesh Mesh(CadPart part){return SceneMesher.BuildPrint(part,CancellationToken.None);}
  public static void Stl(CadPart part,Stream stream){var mesh=Mesh(part);if(mesh.Indices.Length==0||mesh.SignedVolume()<=0)throw new Exception("Некорректная сетка: "+part.Label);double x=(mesh.Points.Min(v=>v.X)+mesh.Points.Max(v=>v.X))/2,y=(mesh.Points.Min(v=>v.Y)+mesh.Points.Max(v=>v.Y))/2,z=mesh.Points.Min(v=>v.Z);using(var writer=new BinaryWriter(stream,Encoding.ASCII,true)){var head=new byte[80];Encoding.ASCII.GetBytes("GearLab 1.3 binary STL; units=mm; part="+part.Id).Take(80).ToArray().CopyTo(head,0);writer.Write(head);writer.Write((uint)mesh.Triangles);for(int j=0;j<mesh.Indices.Length;j+=3){var a=mesh.Points[mesh.Indices[j]];var b=mesh.Points[mesh.Indices[j+1]];var c=mesh.Points[mesh.Indices[j+2]];var n=Vector3D.CrossProduct(b-a,c-a);n.Normalize();writer.Write((float)n.X);writer.Write((float)n.Y);writer.Write((float)n.Z);foreach(var v in new[]{a,b,c}){writer.Write((float)(v.X-x));writer.Write((float)(v.Y-y));writer.Write((float)(v.Z-z));}writer.Write((ushort)0);}}}
  public static void Zip(CadAssembly model,string path){if(!model.Valid)throw new Exception("Нет допустимых деталей для печати.");string full=Path.GetFullPath(path),temp=Path.Combine(Path.GetDirectoryName(full),".gearlab-print-"+Guid.NewGuid().ToString("N")+".tmp");try{using(var output=File.Create(temp))using(var archive=new ZipArchive(output,ZipArchiveMode.Create)){var manifest=new StringBuilder("Файл;Деталь;Количество;Размер X мм;Размер Y мм;Размер Z мм\r\n");foreach(var part in model.Parts){if(!Candidate(part))throw new Exception("Непечатный компонент: "+part.Label);string name=part.Id+".stl";using(var stream=archive.CreateEntry(name,CompressionLevel.Optimal).Open())Stl(part,stream);var b=new CadAssembly();b.Parts.Add(part);var dims=b.Bounds();manifest.AppendLine(name+";\""+part.Label.Replace("\"","\"\"")+"\";1;"+Engine.F(dims[1]-dims[0])+";"+Engine.F(dims[3]-dims[2])+";"+Engine.F(dims[5]-dims[4]));}using(var w=new StreamWriter(archive.CreateEntry("Состав.csv").Open(),new UTF8Encoding(true)))w.Write(manifest);using(var w=new StreamWriter(archive.CreateEntry("Прочитай_перед_печатью.txt").Open(),new UTF8Encoding(true)))w.Write("Каждый STL — отдельная деталь в миллиметрах. При импорте выберите мм: STL сам по себе не хранит стандартных единиц. Каждая деталь центрирована по XY, нижняя точка Z=0. Один файл соответствует одному экземпляру; повторяющиеся детали сохранены отдельно. Не включайте автоматическое масштабирование до стола.\r\nСначала проверьте размеры в слайсере, зазоры/усадку, направление слоёв и опоры. Экспорт не подтверждает прочность пластикового редуктора. Водила с валом — геометрические заготовки: способ передачи момента и материал не рассчитаны. Круги аппроксимированы с целевой погрешностью хорды 0,01 мм; зубчатые профили наследуют дискретизацию расчёта. Встроенные зацепы не вращаются на осях: контакт со скольжением, нужен подбор материала и проверка износа.\r\n");}if(File.Exists(full))File.Replace(temp,full,null);else File.Move(temp,full);}finally{if(File.Exists(temp))File.Delete(temp);}}
 }
 public sealed class PrintDialog:Form {
  readonly ListView list=new ListView();readonly ComboBox format=new ComboBox();readonly Button export=new Button();readonly Label count=new Label();public List<string> SelectedIds{get{return list.CheckedItems.Cast<ListViewItem>().Select(i=>(string)i.Tag).ToList();}}public bool StlZip{get{return format.SelectedIndex==1;}}
  public PrintDialog(CadAssembly model){Text="Детали для 3D-печати";Font=new Font("Segoe UI",10);Size=new Size(920,650);MinimumSize=new Size(660,440);StartPosition=FormStartPosition.CenterParent;AutoScaleMode=AutoScaleMode.Dpi;ShowInTaskbar=false;var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(12),ColumnCount=1,RowCount=5};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,62));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,40));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,65));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,42));Controls.Add(layout);layout.Controls.Add(new Label{Dock=DockStyle.Fill,Text="Выберите корпус, крышки, шестерни и другие печатные заготовки.\nМотор, подшипники, крепёж и отдельные металлические валы/оси не включены."},0,0);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};actions.Controls.Add(B("Все",()=>Set(i=>true)));actions.Controls.Add(B("Корпус и шестерни",()=>Set(i=>((CadPart)i.SubItems[1].Tag).Role=="housing"||((CadPart)i.SubItems[1].Tag).Role=="gear")));actions.Controls.Add(B("Снять всё",()=>Set(i=>false)));count.AutoSize=true;count.Padding=new Padding(8);actions.Controls.Add(count);layout.Controls.Add(actions,0,1);
   list.Dock=DockStyle.Fill;list.View=View.Details;list.CheckBoxes=true;list.FullRowSelect=true;list.HideSelection=false;list.AccessibleName="Выбор печатных деталей";list.Columns.Add("Деталь",510);list.Columns.Add("Габарит, мм",240);foreach(var p in model.Parts.Where(PrintExport.Candidate)){var single=new CadAssembly();single.Parts.Add(p);var b=single.Bounds();var item=new ListViewItem(p.Label+" · "+p.Id){Tag=p.Id,Checked=true};item.SubItems.Add(Engine.F(b[1]-b[0])+" × "+Engine.F(b[3]-b[2])+" × "+Engine.F(b[5]-b[4])).Tag=p;list.Items.Add(item);}list.ItemChecked+=(s,e)=>UpdateCount();layout.Controls.Add(list,0,2);layout.Controls.Add(new Label{Dock=DockStyle.Fill,Text="STEP: выбранные детали в положении сборки. ZIP/STL: отдельный файл для каждой детали, Z=0.\nЭто геометрия для подготовки печати: материал, зазоры и прочность нужно проверить.\nВстроенные зацепы циклоидального корпуса включаются флажком в основной программе.",ForeColor=Color.SlateGray,Font=new Font("Segoe UI",9)},0,3);var bottom=new FlowLayoutPanel{Dock=DockStyle.Fill};format.DropDownStyle=ComboBoxStyle.DropDownList;format.Width=290;format.AccessibleName="Формат печатных деталей";format.Items.AddRange(new[]{"STEP — выбранные детали сборки","ZIP — отдельные STL + список деталей"});format.SelectedIndex=1;bottom.Controls.Add(format);export.Text="Экспортировать…";export.Width=160;export.Height=32;export.Click+=(s,e)=>{if(SelectedIds.Count>0)DialogResult=DialogResult.OK;};bottom.Controls.Add(export);var cancel=new Button{Text="Отмена",DialogResult=DialogResult.Cancel,Width=90,Height=32};bottom.Controls.Add(cancel);CancelButton=cancel;AcceptButton=export;layout.Controls.Add(bottom,0,4);UpdateCount();
  }
  static Button B(string text,Action action){var b=new Button{Text=text,AutoSize=true,Height=30};b.Click+=(s,e)=>action();return b;}
  void Set(Func<ListViewItem,bool> predicate){list.BeginUpdate();foreach(ListViewItem i in list.Items)i.Checked=predicate(i);list.EndUpdate();UpdateCount();}
  void UpdateCount(){count.Text="Выбрано: "+list.CheckedItems.Count;export.Enabled=list.CheckedItems.Count>0;}
 }
 public partial class MainForm {
  void ExportPrint(){if(!ReadControls())return;Recalculate();if(!result.Valid||!result.Model.Valid){dialogs.Info(this,"Исправьте ошибки расчёта и полной 3D-сборки перед экспортом.","Печать");return;}bool playing=canvas.ShowMotion;canvas.ShowMotion=false;try{using(var selection=new PrintDialog(result.Model)){if(selection.ShowDialog(this)!=DialogResult.OK)return;var parts=PrintExport.Select(result.Model,selection.SelectedIds);string type=selection.StlZip?"zip":"step",path=dialogs.Save(this,type,"Печать_"+kinds[p.Kind]+(p.CycloidLayout==1?"_Micro":"")+"_"+Engine.N(p.Ratio)+"к1."+type);if(path==null)return;Attempt(()=>{Cursor=Cursors.WaitCursor;try{if(selection.StlZip)PrintExport.Zip(parts,path);else StepExport.Write(parts,path);}finally{Cursor=Cursors.Default;}footer.Text="Печатные детали сохранены: "+path;});}}finally{canvas.ShowMotion=playing;}}
 }
}
